import * as THREE from 'three/webgpu';
import { mix, color, uv } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
	// ---- constants ----
	const TILE_W = 1.0;
	const TILE_H = 0.62;
	const GAP = 0.25; // base unit
	const COLS = 3;
	const ROWS = 2;
	const GRID_W = COLS * TILE_W + (COLS - 1) * GAP; // 3*1 + 2*0.25 = 3.5
	const GRID_H = ROWS * TILE_H + (ROWS - 1) * GAP; // 2*0.62 + 1*0.25 = 1.49

	const GRAD_TOP = '#1a1a22';
	const GRAD_BOTTOM = '#121218';
	const TILE_COLOR = '#e8ecf2';
	const TILE_OPACITY = 0.78;

	const KICKER_TEXT = 'AS FEATURED IN';
	const BRAND_TEXTS = [
		'HODINKEE',
		'MONOCLE',
		'WALLPAPER',
		'ESQUIRE',
		'WIRED',
		'FINANCIAL TIMES',
	];

	// ---- group ----
	const group = new THREE.Group();

	// apply placement from config if present
	if (config.position) group.position.fromArray(config.position);
	if (config.rotation) group.rotation.fromArray(config.rotation);
	if (config.scale) group.scale.fromArray(config.scale);

	// ---- create tiles ----
	const tileGeoms = [];
	const tileMats = [];
	const tileMeshes = [];

	for (let row = 0; row < ROWS; row++) {
		for (let col = 0; col < COLS; col++) {
			const ix = row * COLS + col;
			const text = BRAND_TEXTS[ix] || '';

			// geometry
			const geom = new THREE.PlaneGeometry(TILE_W, TILE_H);
			geom.translate(0, 0, 0); // centre
			tileGeoms.push(geom);

			// material – MeshPhysicalNodeMaterial with gradient albedo
			const mat = new THREE.MeshPhysicalNodeMaterial({
				transparent: true,
				opacity: 0, // start invisible for animation
				metalness: 0.5,
				roughness: 0.55,
				clearcoat: 0.2,
				anisotropy: 0.6,
				anisotropyDirection: new THREE.Vector3(1, 0, 0),
			});

			// vertical gradient using node system
			mat.colorNode = mix(
				color(GRAD_TOP),
				color(GRAD_BOTTOM),
				uv().y
			);

			// chamfered edges – approximated via rounded plane geometry not implemented; skip.

			const mesh = new THREE.Mesh(geom, mat);
			mesh.castShadow = true;
			mesh.receiveShadow = true;

			// position in grid (centered)
			const offsetX = -GRID_W / 2 + TILE_W / 2 + col * (TILE_W + GAP);
			const offsetY = GRID_H / 2 - TILE_H / 2 - row * (TILE_H + GAP);
			mesh.position.set(offsetX, offsetY, 0);

			// store for later cleanup
			tileMats.push(mat);
			tileMeshes.push(mesh);
			group.add(mesh);

			// ---- create brand text on tile ----
			if (text) {
				const txtMesh = ctx.fontAtlas.createTextMesh(text, {
					fontFamily: 'JetBrains Mono',
					fontSize: 13,
					fontWeight: 700,
					letterSpacing: 0.08,
					lineHeight: 1,
					color: '#e8ecf2',
					opacity: TILE_OPACITY,
					// align centre
					anchorX: 'center',
					anchorY: 'middle',
				});
				// position text slightly above tile surface to avoid z‑fighting
				txtMesh.position.set(0, 0, 0.001);
				mesh.add(txtMesh);
			}
		}
	}

	// ---- kicker text above grid ----
	const kickerMesh = ctx.fontAtlas.createTextMesh(KICKER_TEXT, {
		fontFamily: 'JetBrains Mono',
		fontSize: 9,
		fontWeight: 700,
		letterSpacing: 0.12,
		lineHeight: 1.2,
		color: '#e8ecf2',
		opacity: 1,
		anchorX: 'center',
		anchorY: 'bottom',
	});
	kickerMesh.position.set(0, GRID_H / 2 + 0.3, 0.001);
	group.add(kickerMesh);

	// ---- GSAP stagger animation (fade‑up) ----
	const tl = gsap.timeline({ defaults: { ease: 'power2.out' } });
	tileMeshes.forEach((mesh, i) => {
		// start slightly higher and invisible (already set opacity 0)
		mesh.position.y += 0.2;
		tl.to(
			mesh.position,
			{
				y: mesh.position.y - 0.2,
				duration: 0.5,
				ease: 'power2.out',
			},
			i * 0.08
		);
		tl.to(
			mesh.material,
			{
				opacity: 1,
				duration: 0.5,
				ease: 'power2.out',
			},
			i * 0.08
		);
	});
	tl.play();

	// ---- cleanup ----
	group.userData.cleanup = () => {
		tl.kill();
		tileGeoms.forEach(g => g.dispose());
		tileMats.forEach(m => m.dispose());
		// dispose any text meshes created by fontAtlas if they expose dispose
		if (kickerMesh.geometry) kickerMesh.geometry.dispose();
		if (kickerMesh.material) kickerMesh.material.dispose();
	};

	// ---- attach empty handlers container ----
	group.userData.handlers = {};

	return group;
}
